import pytest

from minisheet.refs import Ref, parse_range, parse_ref, to_a1


# B§1 table rows
def test_parse_ref_b12():
    assert parse_ref("B12") == Ref(1, 11, False, False)


def test_parse_ref_absolute_max():
    assert parse_ref("$zz$9999") == Ref(701, 9998, True, True)


def test_parse_range_mixed_corners():
    assert parse_range("$C3:A$1") == (Ref(0, 0, False, True), Ref(2, 2, True, False))


def test_to_a1_absolute_col():
    assert to_a1(Ref(26, 0, True, False)) == "$AA1"


def test_parse_ref_a0_rejected():
    with pytest.raises(ValueError):
        parse_ref("A0")


def test_parse_ref_aaa1_rejected():
    with pytest.raises(ValueError):
        parse_ref("AAA1")


# Review Focus
def test_a01_rejected():
    with pytest.raises(ValueError):
        parse_ref("A01")


def test_range_bare_cell():
    with pytest.raises(ValueError):
        parse_range("A1")


def test_to_a1_out_of_range():
    with pytest.raises(ValueError):
        to_a1(Ref(702, 0))


# Additional coverage of the B§1 rules
def test_parse_ref_a1_is_origin():
    assert parse_ref("A1") == Ref(0, 0)


def test_parse_ref_lowercase_and_dollar_flags():
    assert parse_ref("$a$1") == Ref(0, 0, True, True)


def test_parse_ref_max_row_and_col_bounds():
    assert parse_ref("ZZ9999") == Ref(701, 9998)


def test_parse_ref_rejects_trailing_text():
    with pytest.raises(ValueError):
        parse_ref("A1x")


def test_parse_ref_rejects_one_letter_only():
    with pytest.raises(ValueError):
        parse_ref("12")


def test_parse_ref_rejects_row_10000():
    with pytest.raises(ValueError):
        parse_ref("A10000")


def test_parse_range_single_cell_valid():
    assert parse_range("A1:A1") == (Ref(0, 0), Ref(0, 0))


def test_parse_range_normalizes_order():
    assert parse_range("C3:A1") == (Ref(0, 0), Ref(2, 2))


def test_parse_range_tie_takes_first_corner_flags():
    # Same column on both corners: min and max col both come from the first corner.
    assert parse_range("$A1:$A5") == (Ref(0, 0, True, False), Ref(0, 4, True, False))


def test_to_a1_plain():
    assert to_a1(Ref(0, 0)) == "A1"


def test_to_a1_both_flags_uppercase():
    assert to_a1(Ref(701, 9998, True, True)) == "$ZZ$9999"


def test_to_a1_row_flag_only():
    assert to_a1(Ref(1, 11, False, True)) == "B$12"


def test_to_a1_negative_row_rejected():
    with pytest.raises(ValueError):
        to_a1(Ref(0, -1))


def test_to_a1_row_too_large_rejected():
    with pytest.raises(ValueError):
        to_a1(Ref(0, 9999))

