import re
from dataclasses import dataclass


@dataclass(frozen=True)
class Ref:
    col: int
    row: int
    abs_col: bool = False
    abs_row: bool = False

__all__ = ["parse_ref", "parse_range", "to_a1"]

_REF_RE = re.compile(r"(\$?)([A-Za-z]{1,2})(\$?)([1-9][0-9]{0,3})")
_MAX_COL = 701
_MAX_ROW = 9998


def parse_ref(s: str) -> Ref:
    """Parse a single A1-style reference such as ``B12`` or ``$A$1``."""
    m = _REF_RE.fullmatch(s)
    if m is None:
        raise ValueError(f"invalid reference: {s!r}")
    abs_col = m.group(1) == "$"
    letters = m.group(2).upper()
    abs_row = m.group(3) == "$"
    col = 0
    for ch in letters:
        col = col * 26 + (ord(ch) - ord("A") + 1)
    col -= 1
    row = int(m.group(4)) - 1
    return Ref(col, row, abs_col, abs_row)


def parse_range(s: str) -> tuple[Ref, Ref]:
    """Parse ``ref:ref`` into (top-left, bottom-right) with per-axis $ flags."""
    parts = s.split(":")
    if len(parts) != 2:
        raise ValueError(f"invalid range: {s!r}")
    a = parse_ref(parts[0])
    b = parse_ref(parts[1])
    # Each axis: the corner supplying min/max supplies the $ flag (tie: first corner).
    if a.col <= b.col:
        min_col, min_abs_col = a.col, a.abs_col
    else:
        min_col, min_abs_col = b.col, b.abs_col
    if a.col >= b.col:
        max_col, max_abs_col = a.col, a.abs_col
    else:
        max_col, max_abs_col = b.col, b.abs_col
    if a.row <= b.row:
        min_row, min_abs_row = a.row, a.abs_row
    else:
        min_row, min_abs_row = b.row, b.abs_row
    if a.row >= b.row:
        max_row, max_abs_row = a.row, a.abs_row
    else:
        max_row, max_abs_row = b.row, b.abs_row
    return (
        Ref(min_col, min_row, min_abs_col, min_abs_row),
        Ref(max_col, max_row, max_abs_col, max_abs_row),
    )


def to_a1(ref: Ref) -> str:
    """Render a Ref as uppercase A1 text, with ``$`` flags where set."""
    if not (0 <= ref.col <= _MAX_COL and 0 <= ref.row <= _MAX_ROW):
        raise ValueError(f"reference out of range: col={ref.col} row={ref.row}")
    n = ref.col + 1
    letters = ""
    while n:
        n, r = divmod(n - 1, 26)
        letters = chr(ord("A") + r) + letters
    col_part = ("$" if ref.abs_col else "") + letters
    row_part = ("$" if ref.abs_row else "") + str(ref.row + 1)
    return col_part + row_part

